export const meta = {
  "slug": "chips",
  "name": "Chips",
  "family": "Inputs",
  "collection": "Interface",
  "component": "createLinearChips"
};

export function createLinearChips(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderLinearScene(svg, current);
  };
  render();
  const controller = bindLinearScene(root, current);
  return {
    replay: controller.replay,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
  };
}
